INSERT INTO question_bank_2_examples (id, group_id, content, sequence)
VALUES (
  '87725260-f3a7-5e11-a341-fa0706221003', 'fa121196-c7a5-56b7-87cd-b05a7498e103',
  'Cho hai hàm `bar` và `foo` được viết bằng ngôn ngữ C++ như sau. Giá trị của `foo(x,y)` được thể hiện bởi biểu thức

```cpp
int bar(int x, int y) {
    if (y == 0) return 0;
    return (x + bar(x, y - 1));
}

int foo(int a, int b) {
    if (b == 0) return 1;
    return bar(a, foo(a, b - 1));
}
```

Lựa chọn:
- $x * y$
- $x + x * y$
- $y + x * y$
- $y^x$
- $x^y$', 1
);

