INSERT INTO question_bank_2_examples (id, group_id, content, sequence)
VALUES (
  '8ff3291f-ac52-5add-9796-61c2cb450285', 'fa121196-c7a5-56b7-87cd-b05a7498e103',
  'Hoàn thiện hàm `move` để hàm này xuất ra kết quả của bài toán "Tháp Hà Nội". Chọn một.

```cpp
void move(int n, char src, char dest, char aux) {
    if (n == 1)
        cout << "Move from " << src << " to " << dest << endl;
    else {
        // TODO
    }
}
```

Lựa chọn:
- ```cpp
move(n - 1, src, aux, dest);
move(1, src, dest, aux);
move(n - 1, aux, dest, src);
```
- ```cpp
move(n - 1, src, aux, dest);
move(1, dest, src, aux);
move(n - 1, aux, dest, src);
```
- ```cpp
move(n - 1, src, aux, dest);
move(1, src, aux, dest);
move(n - 1, aux, dest, src);
```
- ```cpp
move(n - 1, src, dest, aux);
move(1, src, dest, aux);
move(n - 1, dest, src, aux);
```
- ```cpp
move(n - 1, aux, src, dest);
move(1, src, aux, dest);
move(n - 1, dest, src, aux);
```', 5
);

