INSERT INTO question_bank_2_examples (id, group_id, content, sequence)
VALUES (
  'b3f495ab-ec56-58c5-b8d1-6116a0b590c6', 'fa121196-c7a5-56b7-87cd-b05a7498e103',
  'Cho đoạn giải thuật đệ quy như sau:

```cpp
binary_search(A, T, L, R) {
    m = (L + R) / 2;
    if (A[m] == T) return m;
    else if (A[m] < T)
        return binary_search(A, T, m + 1, R);
    else
        return binary_search(A, T, L, m - 1);
}
```

Nhận xét nào sau đây đúng? Chọn một.

Lựa chọn:
- Đệ quy không dừng lại khi T không ở trong A (lỗi khi truy cập ngoài giới hạn của A)
- Thiếu trường hợp tổng quát (General case)
- Không có vấn đề
- Thiếu trường hợp dừng (Base case)
- Đệ quy không dừng lại khi T nằm giữa A', 13
);

